import sys

def solve(n, k):
    if k == 0:
        pairs = [(i, n - 1 - i) for i in range(n // 2)]
    elif k == n - 1:
        pairs = [(i, i) for i in range(n // 2)]
    else:
        return -1

    return pairs

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1
        k = int(data[index])
        index += 1

        result = solve(n, k)
        if result == -1:
            results.append("-1")
        else:
            results.append("\n".join(f"{a} {b}" for a, b in result))

    print("\n\n".join(results))

if __name__ == "__main__":
    main()
